/* Public price snapshots. Missing observations are null; no synthetic prices or chart history. */
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?Math.round(n).toLocaleString('en-US'):'—';
const fmt=n=>!Number.isFinite(n)?'—':Math.abs(n)>=1e9?+(n/1e9).toFixed(2)+'B':Math.abs(n)>=1e6?+(n/1e6).toFixed(2)+'M':Math.abs(n)>=1e3?+(n/1e3).toFixed(2)+'K':+n.toFixed(2);
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Browser storage unavailable. Changes last for this visit.')}}
const DATA=window.DT_DATA.items,META=window.DT_DATA.meta,RECIPES=window.DT_DATA.recipes,byId=new Map(DATA.map(d=>[d.id,d]));
const investmentIds=['elytra','dragon_head','piglin_head','enchanted_golden_apple'];
let watch=new Set(read('dt-watch-v2',[])),plans=read('dt-plans-v2',[]),profile=read('dt-profile',''),history=read('dt-history-v2',{});
let state={route:'home',query:'',category:'All',page:1,size:40,sort:'name',dir:1,flipTab:'crafting',budget:0,minProfit:0};
let currentItem=null,context='market',returnFocus=null,observers=[],toastTimer,scrollBusy=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const snapshotTime=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(META.sourceTime));
const icon=d=>d.icon?`<img class="item-icon ${d.cube?'cube-icon':''} ${d.animated?'animated-icon':''}" src="assets/${esc(d.icon)}" alt="" width="32" height="32" loading="lazy">`:`<span class="item-placeholder" aria-hidden="true">${esc(d.name[0])}</span>`;
const price=d=>Number.isFinite(d.price)?`<span title="${num(d.price)} in-game dollars; rounded public quote">${d.rounded?'≈ ':''}${fmt(d.price)}</span>`:'<span class="price-unavailable">No quote</span>';
const movement=d=>Number.isFinite(d.change)?`<span class="${d.change<0?'negative':'positive'}">${d.change>0?'+':''}${d.change.toFixed(1)}%</span>`:'<span class="price-unavailable">—</span>';
const monthly=d=>Number.isFinite(history[d.id]?.average)?`<span title="Volume-weighted mean of imported October transactions">${fmt(history[d.id].average)}*</span>`:'<span class="price-unavailable">Unavailable</span>';
const star=d=>`<button class="watch-button ${watch.has(d.id)?'saved':''}" data-watch="${d.id}" aria-pressed="${watch.has(d.id)}" aria-label="${watch.has(d.id)?'Remove':'Add'} ${esc(d.name)} ${watch.has(d.id)?'from':'to'} watchlist">${watch.has(d.id)?'★':'☆'}</button>`;
const itemName=d=>`<span class="item-name">${icon(d)}<span>${esc(d.name)}<small>${esc(d.category)}${d.variantNote?' · Check variant':''}</small></span></span>`;
function toast(s){clearTimeout(toastTimer);$('.toast').textContent=s;$('.toast').classList.add('show');toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3200)}
function updateStars(){ $('#watch-count').textContent=watch.size;$$('[data-watch]').forEach(b=>{let d=byId.get(b.dataset.watch);if(!d)return;const yes=watch.has(d.id);b.classList.toggle('saved',yes);b.textContent=yes?'★':'☆';b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',`${yes?'Remove':'Add'} ${d.name} ${yes?'from':'to'} watchlist`)})}
function toggleWatch(id){let d=byId.get(id);if(!d)return;watch.has(id)?watch.delete(id):watch.add(id);save('dt-watch-v2',[...watch]);updateStars();toast(watch.has(id)?`${d.name} saved`:`${d.name} removed`);if(state.route==='watchlist')updateResults()}
function craft(d){const recipes=RECIPES[d.id];if(!recipes||!Number.isFinite(d.price))return null;let best=null;for(const r of recipes){let total=0,lines=[],valid=true;for(const [id,count] of Object.entries(r.ingredients)){let x=byId.get(id);if(!x||!Number.isFinite(x.price)){valid=false;break}total+=x.price*count;lines.push({id,name:x.name,count,price:x.price})}if(valid){let cost=total/r.yield;if(!best||cost<best.cost)best={cost,yield:r.yield,lines,profit:d.price-cost,roi:(d.price-cost)/cost*100}}}return best}
const craftData=DATA.map(d=>({...d,recipe:craft(d)})).filter(d=>d.recipe&&d.recipe.cost>0);
function stats(){return `<div class="wrap stats-strip reveal"><div class="stat"><div class="stat-label">Minecraft items · Java 26.1</div><div class="stat-value">${num(META.catalogCount)}<small>Full versioned registry</small></div></div><div class="stat"><div class="stat-label">Published market quotes</div><div class="stat-value">${num(META.priceCount)}<small>Rounded source prices</small></div></div><div class="stat"><div class="stat-label">Recipes with priced ingredients</div><div class="stat-value">${num(craftData.length)}<small>Costs calculated per output</small></div></div><div class="stat"><div class="stat-label">Public price snapshot</div><div class="stat-value" style="font-size:19px">Oct 21, 2026<small>10:49 AM PDT · Not a live feed</small></div></div></div>`}
function sourceBanner(){return `<div class="source-status"><span><span class="coverage-dot"></span>Public price snapshot · Monthly averages require dated sales history.</span><button data-info="data">Sources & coverage ↗</button></div>`}
function miniInvest(){return `<div class="invest-mini">${investmentIds.map(id=>byId.get(id)).filter(Boolean).map(d=>`<div class="invest-mini-row"><button data-item="${d.id}" aria-label="View ${esc(d.name)}">${icon(d)}</button><button data-item="${d.id}" class="item-detail"><strong>${esc(d.name)}</strong><small>${d.category}</small></button><div class="investment-value">${price(d)}<small>${movement(d)} / 7d</small></div>${star(d)}</div>`).join('')}</div>`}
function cards(data){return `<div class="investment-grid">${data.map((d,i)=>`<article class="investment-card reveal" style="--delay:${i%4*45}ms" data-item="${d.id}" tabindex="0" aria-label="View ${esc(d.name)}"><span class="card-index">${esc(d.category.toUpperCase())}</span>${star(d)}${icon(d)}<h3>${esc(d.name)}</h3><div class="card-price">${price(d)} ${movement(d)}</div><div class="monthly-line"><span>October average</span>${monthly(d)}</div><div class="card-bottom"><span>PUBLIC QUOTE · 7D CHANGE</span><span>↗</span></div></article>`).join('')}</div>`}
function recipeTable(data,full=false){return `<div class="table-scroll"><table class="market-table"><thead><tr><th>Item</th><th>Craft cost / item</th><th>Market quote</th><th>Recipe spread</th><th>ROI</th>${full?'<th>Save</th>':''}</tr></thead><tbody>${data.map(d=>`<tr data-item="${d.id}" data-context="crafting" tabindex="0" aria-label="View ${esc(d.name)} recipe"><td>${itemName(d)}</td><td>≈ ${fmt(d.recipe.cost)}</td><td>${price(d)}</td><td class="${d.recipe.profit>=0?'positive':'negative'}">${d.recipe.profit>0?'+':''}${fmt(d.recipe.profit)}</td><td class="${d.recipe.roi>=0?'positive':'negative'}">${d.recipe.roi.toFixed(1)}%</td>${full?`<td>${star(d)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function home(){let preferred=['beacon','diamond_chestplate','diamond_leggings','diamond_boots','firework_rocket'];let crafts=preferred.map(id=>craftData.find(d=>d.id===id)).filter(Boolean);return `<div class="page-enter"><section class="wrap hero"><div class="hero-copy"><div class="eyebrow">DONUT SMP · AUCTION & CRAFTING</div><h1>Market overview</h1><p class="hero-desc">Item prices, crafting costs, investments, and spawner calculations.</p><div class="hero-buttons"><a class="btn btn-primary" href="#/market">All ${num(DATA.length)} entries <span>↗</span></a><a class="text-link" href="#/flips">Compare crafting <span>→</span></a></div><div class="home-search-wrap"><form class="hero-search" id="home-search-form" role="search"><span aria-hidden="true">⌕</span><label class="visually-hidden" for="home-search">Search the item catalog</label><input id="home-search" autocomplete="off" placeholder="Search every item by name or Minecraft ID…"><kbd>/</kbd></form><div id="home-results"></div></div></div><div class="hero-stage" data-tilt><img class="spawner-art" src="assets/spawner.png" alt="Skeleton spawner" width="1402" height="1122" fetchpriority="high"><div class="price-tag"><small>SKELETON SPAWNER</small><strong>Price unverified</strong><a href="#/spawners">Open calculator ↗</a></div></div></section>${stats()}<section class="wrap market-section">${sourceBanner()}<div class="market-layout"><div class="reveal"><div class="panel-title"><h3>Crafting spreads</h3><a class="text-link" href="#/flips?tab=crafting">All recipes <span>↗</span></a></div>${recipeTable(crafts)}<p class="table-note">Computed from rounded market quotes. A spread is not a confirmed buyer or a realized profit.</p></div><div class="reveal" style="--delay:80ms"><div class="panel-title"><h3>Popular investments</h3><a class="text-link" href="#/investments">View all <span>↗</span></a></div>${miniInvest()}<p class="table-note">Current imported source quote · Change reported by the source over 7 days.</p></div></div></section><section class="wrap dashboard-tools"><a href="#/spawners" class="dashboard-tool reveal"><span>▦</span><div><h3>Spawner calculator</h3><p>Use your measured output and purchase price.</p></div><span>↗</span></a><a href="#/flips?tab=order" class="dashboard-tool reveal" style="--delay:50ms"><span>⇄</span><div><h3>Order flip planner</h3><p>Compare your buy order with a selling target.</p></div><span>↗</span></a><a href="#/watchlist" class="dashboard-tool reveal" style="--delay:100ms"><span>☆</span><div><h3>Watchlist & trade plans</h3><p>Saved in this browser.</p></div><span>↗</span></a></section></div>`}
function head(title,description,extra=''){return `<section class="wrap page-head page-enter"><div class="page-head-row"><div><h1>${title}</h1><p>${description}</p></div>${extra}</div></section>`}
function filterBar(crafting=false){return `<div class="filter-bar"><div class="search-box"><span>⌕</span><label class="visually-hidden" for="market-search">Search catalog</label><input id="market-search" placeholder="Search item name or Minecraft ID…" value="${esc(state.query)}" autocomplete="off"></div>${crafting?`<div class="filter-field"><label for="budget">Max craft / item</label><input id="budget" type="number" min="0" placeholder="Any" value="${state.budget||''}"></div>`:''}<div class="filter-field"><label for="sort">Sort</label><select id="sort"><option value="name">Name A–Z</option><option value="price">Highest price</option><option value="change">7d gainers</option>${crafting?'<option value="profit">Recipe spread</option><option value="roi">Crafting ROI</option>':''}</select></div></div>`}
function marketPage(){return `${head('Item catalog',`${num(META.catalogCount)} Minecraft Java 26.1 items plus identified server items and variants. ${num(META.priceCount)} published quotes; unavailable prices stay blank.`)}<section class="wrap page-main page-enter">${sourceBanner()}${filterBar()}<div class="chips" aria-label="Item category">${['All','Priced','Blocks','Equipment','Redstone','Materials','Collectibles','Consumables','DonutSMP','Server variants'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div id="results"></div><div id="pagination"></div></section>`}
function planner(){return `<div class="manual-planner"><h3>Order / auction flip planner</h3><p>Enter an observed buy price and selling target. No order-book feed is connected.</p><form id="manual-plan"><div class="planner-fields"><div><label for="plan-item">Item</label><input id="plan-item" list="item-options" placeholder="Search an item…" required><datalist id="item-options">${DATA.map(d=>`<option value="${esc(d.name)} — ${d.id}"></option>`).join('')}</datalist></div><div><label for="manual-buy">Buy / item</label><input id="manual-buy" type="number" min="0.01" step="0.01" required></div><div><label for="manual-sell">Sell / item</label><input id="manual-sell" type="number" min="0.01" step="0.01" required></div><div><label for="manual-qty">Quantity</label><input id="manual-qty" type="number" min="1" max="1000000" value="64" required></div><button class="btn btn-primary" type="submit">Save plan <span>↗</span></button></div><div class="manual-summary"><span>Capital <strong id="manual-capital">—</strong></span><span>Spread <strong id="manual-profit">—</strong></span></div></form></div>`}
function flipsPage(){return `${head('Flips & crafting','Recipe costs use sourced ingredient quotes. Order and auction plans use prices you enter.')}<section class="wrap page-main page-enter"><div class="tabs page-tabs" role="tablist" aria-label="Flip type">${[['crafting','Crafting flips'],['order','Order flips'],['auction','Auction flips']].map(([id,name])=>`<button class="tab ${state.flipTab===id?'active':''}" role="tab" aria-selected="${state.flipTab===id}" data-flip-tab="${id}">${name}</button>`).join('')}</div><div id="flip-view">${state.flipTab==='crafting'?`${sourceBanner()}${filterBar(true)}<div id="results"></div><div id="pagination"></div>`:planner()+`<div class="section-head"><h3>Saved trade plans</h3><a class="text-link" href="#/watchlist">Your watchlist <span>↗</span></a></div><div id="plans-list">${planList()}</div>`}</div></section>`}
function calculator(){const bone=byId.get('bone');return `<div class="calculator advanced-calc" data-calculator><div class="calc-top"><strong>Farm income estimate</strong><small>YOUR INPUTS</small></div><label class="range-label" for="spawner-count">Spawner count <output data-out="count">12</output></label><input class="range" id="spawner-count" data-calc="count" type="range" min="1" max="128" value="12"><label class="range-label" for="online-hours">Online hours / day <output data-out="hours">6 hours</output></label><input class="range" id="online-hours" data-calc="hours" type="range" min="1" max="24" value="6"><div class="calc-field"><label for="calc-price">Your price / spawner</label><input id="calc-price" data-calc="price" type="number" min="0.01" step="0.01" placeholder="Enter price"></div><div class="calc-field"><label for="calc-rate">Measured drops / spawner / hour</label><input id="calc-rate" data-calc="rate" type="number" min="0.01" step="0.01" placeholder="Enter output"></div><div class="calc-field"><label for="calc-drop">Selling price / bone</label><input id="calc-drop" data-calc="drop" type="number" min="0.01" step="0.01" value="${bone?.price??''}"></div><div class="calc-result"><div><small>Estimated income / day</small><strong data-out="income">—</strong></div><div class="payback"><small>Time to payback</small><strong data-out="payback">—</strong></div></div><p class="calc-note">Enter your farm output and purchase price. Bone price, where filled, is an imported public quote, not a guaranteed sale.</p></div>`}
function spawnerPage(){return `${head('Spawner calculator','Estimate income and payback using your own measured production. The skeleton spawner purchase price is unverified.')}<section class="wrap page-main page-enter"><div class="spawner-page-grid"><div class="spawner-visual"><img src="assets/spawner.png" alt="Skeleton spawner" width="1402" height="1122"><span class="section-tag">SKELETON SPAWNER · ENTER YOUR PURCHASE PRICE</span></div>${calculator()}</div><details class="assumptions"><summary>Calculation & assumptions</summary><p>Daily income = count × online hours × measured drops per spawner/hour × sale price per drop. Payback = total purchase cost ÷ daily income. Enter measured production that accounts for your farm layout, stacking behavior, and server mechanics. Storage limits, downtime, unsold inventory, and other costs are not modeled.</p></details></section>`}
function investmentPage(){return `${head('Popular investments','Source-reported market prices and seven-day changes. Monthly averages appear only when dated sales history has been imported.')}<section class="wrap page-main page-enter">${sourceBanner()}${cards(investmentIds.map(id=>byId.get(id)).filter(Boolean))}<div class="section-head" style="margin-top:35px"><h3>Materials</h3><a class="text-link" href="#/market">Full catalog <span>↗</span></a></div>${cards(['netherite_ingot','diamond','gold_ingot','bone_block'].map(id=>byId.get(id)).filter(Boolean))}</section>`}
function planList(){return plans.length?plans.map((p,i)=>{const d=byId.get(p.id);return d?`<div class="journal-row"><div>${itemName(d)}<small class="muted">${num(p.qty)} items · ${esc(p.method)} · Unrealized</small></div><div><small class="muted">Planned spread</small><br><strong class="${p.profit>=0?'positive':'negative'}">${p.profit>0?'+':''}${fmt(p.profit)}</strong></div><button class="text-link" data-remove-plan="${i}">Remove ×</button></div>`:''}).join(''):`<div class="page-empty"><strong>No trade plans saved</strong>Open a recipe or enter prices in the order flip planner.</div>`}
function watchlistPage(){return `${head(profile?`${esc(profile)}’s watchlist`:'Watchlist & plans','Items and trade plans are saved in this browser.',`<a class="btn btn-ghost" href="#/market">Browse items <span>↗</span></a>`)}<section class="wrap page-main page-enter"><div id="results"></div><div class="journal-section"><div class="section-head"><h3>Trade plans</h3><span class="section-tag">${plans.length} SAVED</span></div><div id="plans-list">${planList()}</div></div></section>`}
function marketTable(data){return `<div class="table-scroll"><table class="market-table"><thead><tr><th>Item</th><th><button class="sort-btn" data-sort="price">Public price ↕</button></th><th><button class="sort-btn" data-sort="change">7d change ↕</button></th><th>October average</th><th>Stack</th><th>Save</th></tr></thead><tbody>${data.map(d=>`<tr data-item="${d.id}" tabindex="0" aria-label="View ${esc(d.name)}"><td>${itemName(d)}</td><td>${price(d)}</td><td>${movement(d)}</td><td>${monthly(d)}</td><td class="muted">${d.stack??'—'}</td><td>${star(d)}</td></tr>`).join('')}</tbody></table></div>`}
function filtered(){let data=state.route==='flips'?craftData:DATA;const terms=state.query.toLowerCase().split(/\s+/).filter(Boolean);data=data.filter(d=>terms.every(q=>(d.name+' '+d.id).toLowerCase().includes(q))&&(state.category==='All'||state.category==='Priced'&&Number.isFinite(d.price)||d.category===state.category));if(state.route==='watchlist')data=data.filter(d=>watch.has(d.id));if(state.route==='flips'&&state.budget)data=data.filter(d=>d.recipe.cost<=state.budget);let val=d=>state.sort==='name'?d.name:state.sort==='profit'?d.recipe?.profit:state.sort==='roi'?d.recipe?.roi:d[state.sort];return data.slice().sort((a,b)=>{let x=val(a),y=val(b);if(x==null&&y==null)return a.name.localeCompare(b.name);if(x==null)return 1;if(y==null)return-1;return (typeof x==='string'?x.localeCompare(y):x-y)*state.dir})}
function updateResults(){const root=$('#results');if(!root)return;let data=filtered();if(state.route==='watchlist'){root.innerHTML=data.length?cards(data):`<div class="empty-state"><span class="icon-star">☆</span><h3>No items saved</h3><p>Use the star beside any item to add it here.</p><a class="btn btn-primary" href="#/market">Browse catalog <span>↗</span></a></div>`;observe();return}const total=data.length,pages=Math.max(1,Math.ceil(total/state.size));state.page=Math.min(state.page,pages);const offset=(state.page-1)*state.size,slice=data.slice(offset,offset+state.size);root.innerHTML=slice.length?`<div class="full-table">${state.route==='flips'?recipeTable(slice,true):marketTable(slice)}</div>`:`<div class="empty-state"><h3>No matching items</h3><p>Try another search or category.</p><button class="btn btn-ghost" data-action="reset">Reset filters</button></div>`;$('#pagination').innerHTML=`<div class="pagination"><span>${total?offset+1:0}–${Math.min(offset+state.size,total)} of ${num(total)} entries</span><div><label class="visually-hidden" for="page-size">Rows per page</label><select id="page-size"><option value="20" ${state.size===20?'selected':''}>20 rows</option><option value="40" ${state.size===40?'selected':''}>40 rows</option><option value="80" ${state.size===80?'selected':''}>80 rows</option></select><button data-page="prev" ${state.page===1?'disabled':''}>← Previous</button><span>${state.page} / ${pages}</span><button data-page="next" ${state.page===pages?'disabled':''}>Next →</button></div></div>`}
function route(){closeModal(false);observers.forEach(o=>o.disconnect());observers=[];const raw=location.hash.replace(/^#\/?/,'')||'home',[r,q]=raw.split('?');const url=new URLSearchParams(q);let next=['home','market','flips','spawners','investments','watchlist'].includes(r)?r:'home';state={...state,route:next,query:url.get('q')||'',category:'All',page:1,sort:next==='flips'?'profit':'name',dir:next==='flips'?-1:1,flipTab:['crafting','order','auction'].includes(url.get('tab'))?url.get('tab'):'crafting',budget:0};const pages={home,market:marketPage,flips:flipsPage,spawners:spawnerPage,investments:investmentPage,watchlist:watchlistPage};$('#content').innerHTML=pages[next]();document.title=`${({home:'Market overview',market:'Item catalog',flips:'Flips & crafting',spawners:'Spawner calculator',investments:'Investments',watchlist:'Watchlist'})[next]} — Donut Tracker`;$$('[data-route]').forEach(a=>{const yes=a.dataset.route===next;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('.desktop-nav').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');if($('#sort'))$('#sort').value=state.sort;updateResults();updateStars();observe();scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true});bindTilt();onScroll()}
function observe(){const observer=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('visible');observer.unobserve(x.target)}}),{threshold:.03});$$('.reveal:not(.visible)').forEach(el=>observer.observe(el));observers.push(observer)}
function onScroll(){if(scrollBusy)return;scrollBusy=true;requestAnimationFrame(()=>{scrollBusy=false;const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.width=`${max>0?scrollY/max*100:0}%`;$('#header').classList.toggle('scrolled',scrollY>20)})}
function bindTilt(){const stage=$('[data-tilt]');if(!stage)return;stage.addEventListener('pointermove',ev=>{if(reduced.matches||ev.pointerType==='touch')return;const r=stage.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width-.5,y=(ev.clientY-r.top)/r.height-.5;$('.spawner-art',stage).style.setProperty('--rx',`${-y*6}deg`);$('.spawner-art',stage).style.setProperty('--ry',`${x*8}deg`)});stage.addEventListener('pointerleave',()=>{const a=$('.spawner-art',stage);a.style.setProperty('--rx','0deg');a.style.setProperty('--ry','0deg')})}
function shell(contents,kind='drawer'){return `<div class="modal-backdrop" data-action="close"></div><section class="${kind}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${contents}</section>`}
function showModal(contents,kind='drawer'){returnFocus=document.activeElement;$('#modal-root').innerHTML=shell(contents,kind);document.body.classList.add('no-scroll');$('.drawer-close')?.focus()}
function closeModal(focus=true){$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');currentItem=null;if(focus&&returnFocus?.isConnected)returnFocus.focus()}
function closeButton(){return '<button class="drawer-close" data-action="close" aria-label="Close dialog">×</button>'}
function openItem(id,ctx='market'){const d=byId.get(id);if(!d)return;context=ctx;const recipe=ctx==='crafting'?craft(d):null,alt=window.DT_DATA.alternates[d.id],hist=history[d.id];showModal(`<div class="drawer-top"><small>ITEM DETAILS</small>${closeButton()}</div><div class="detail-heading">${icon(d)}<div><h2 id="dialog-title">${esc(d.name)}</h2><p>${esc(d.id)}</p></div></div><div><span class="detail-price">${price(d)}</span><span class="detail-change">${movement(d)} <span class="muted">/ 7d</span></span></div><div class="detail-metrics"><div><small>October average</small><strong>${monthly(d)}</strong></div><div><small>Stack size</small><strong>${d.stack??'Unverified'}</strong></div></div><div class="detail-source">${d.source?`Source: <a href="${d.source}" target="_blank" rel="noopener noreferrer">DonutSMP Terminal ↗</a><br>Published snapshot: ${snapshotTime}<br>Prices imported from rounded public labels.`:'No verified quote is available for this catalog entry.'}${d.variantNote?`<br>${esc(d.variantNote)}.`:''}${hist?`<br>October import: ${num(hist.transactions)} transactions, ${num(hist.quantity)} items; sample coverage ${esc(hist.first)} to ${esc(hist.last)}. Weighted mean = total unit price × quantity ÷ total quantity.`:''}</div>${alt?`<div class="detail-source">Alternate displayed value: <strong>${fmt(alt.price)}</strong><br><a href="${alt.source}" target="_blank" rel="noopener noreferrer">Donut.Auction ↗</a> · Observed Oct 21. Source history may be stale; this is not a monthly average.</div>`:''}<div class="chart-unavailable">No verified price series imported.<br>Monthly history is not generated from the current quote.</div>${recipe?`<h3 class="recipe-heading">Recipe: ${recipe.yield} output ${recipe.yield===1?'item':'items'}</h3>${recipe.lines.map(l=>`<div class="recipe-line"><span>${num(l.count)} × ${esc(l.name)}</span><strong>≈ ${fmt(l.price*l.count)}</strong></div>`).join('')}<div class="recipe-line"><span>Ingredient cost / output item</span><strong>≈ ${fmt(recipe.cost)}</strong></div>`:''}<div class="trade-plan"><h3>Trade plan</h3><p>Enter your observed prices. No trade is executed.</p><div class="detail-form-row"><div><label for="detail-buy">Buy / item</label><input id="detail-buy" type="number" min="0.01" step="0.01" value="${recipe?recipe.cost.toFixed(2):''}" placeholder="Your buy price"></div><div><label for="detail-sell">Sell / item</label><input id="detail-sell" type="number" min="0.01" step="0.01" value="${d.price??''}" placeholder="Your selling target"></div></div><label class="range-label" for="plan-quantity">Quantity <output id="quantity-output">64 items</output></label><input class="range" id="plan-quantity" type="range" min="1" max="512" value="64"><div class="plan-output"><span>Capital required</span><b id="plan-cost">${recipe?fmt(recipe.cost*64):'—'}</b></div><div class="plan-output"><span>Estimated spread</span><strong id="plan-profit">${recipe?fmt(recipe.profit*64):'—'}</strong></div><button class="btn btn-primary" data-action="save-plan" ${!recipe?'disabled':''}>Save trade plan <span>↗</span></button><p class="calc-note">Selling time, available quantities, and additional costs are not included.</p></div><div class="drawer-actions"><button class="btn btn-ghost" data-action="detail-watch">${watch.has(d.id)?'★ Watching':'☆ Add to watchlist'}</button><button class="btn btn-ghost" data-action="copy-item">Copy Minecraft ID ⧉</button></div>`);currentItem=d}
function updateDetail(){if(!currentItem)return;const b=+$('#detail-buy').value,s=+$('#detail-sell').value,q=+$('#plan-quantity').value;$('#quantity-output').textContent=q+' items';$('#plan-cost').textContent=b>0?fmt(b*q):'—';$('#plan-profit').textContent=b>0&&s>0?fmt((s-b)*q):'—';$('#plan-profit').classList.toggle('negative',s<b);$('[data-action="save-plan"]').disabled=!(b>0&&s>0)}
function calcUpdate(root){const val=(id,def)=>{const x=$(id,root);return x&&x.value!==''?+x.value:def};const count=val('#spawner-count',12),hours=val('#online-hours',6),price=val('#calc-price',0),rate=val('#calc-rate',0),drop=val('#calc-drop',0),income=count*hours*rate*drop; $('[data-out="count"]',root).textContent=count;$('[data-out="hours"]',root).textContent=hours+' hours';$('[data-out="income"]',root).textContent=income>0?fmt(income):'—';$('[data-out="payback"]',root).textContent=income>0&&price>0?fmt(count*price/income)+' days':'—'}
function profileModal(){showModal(`<div class="drawer-top"><small>LOCAL PROFILE</small>${closeButton()}</div><h2 id="dialog-title">Profile name</h2><p>Your profile, watchlist, and trade plans stay in this browser. No Minecraft connection is created.</p><form id="profile-form"><label for="profile-name">Display name</label><input id="profile-name" value="${esc(profile)}" maxlength="24" required autocomplete="nickname"><button class="btn btn-primary" type="submit">Save profile <span>↗</span></button></form>`,'profile-modal');$('#profile-name').focus()}
function sourcesModal(){showModal(`<div class="drawer-top"><small>DATA COVERAGE</small>${closeButton()}</div><h2 id="dialog-title">Sources & coverage</h2><p>The catalog contains all ${num(META.catalogCount)} entries in Minecraft Java 26.1, plus identified server items and source variants. Server availability is not guaranteed for every vanilla item.</p><div class="source-grid"><div><a href="https://github.com/PrismarineJS/minecraft-data" target="_blank" rel="noopener noreferrer">Minecraft catalog & recipes ↗</a><small>PrismarineJS minecraft-data · Java 26.1 registry · MIT license</small></div><div><a href="https://donutsmpterminal.com/all_items" target="_blank" rel="noopener noreferrer">DonutSMP Terminal market quotes ↗</a><small>${num(META.priceCount)} rounded public quotes. Snapshot ${snapshotTime}. Seven-day change is reported by the source; no synthetic history.</small></div><div><a href="https://donut.auction" target="_blank" rel="noopener noreferrer">Donut.Auction alternate displayed values ↗</a><small>25 separately attributed observations. The source warns that transaction history may be incomplete. Values are not October averages.</small></div><div><a href="https://api.donutsmp.net" target="_blank" rel="noopener noreferrer">Official Donut SMP API ↗</a><small>Requires an authorized API key. None is included in this site. Another website’s credentials are not used.</small></div></div><p style="margin-top:22px">A verified month-to-date average requires dated transactions. Import your own October sales CSV to calculate a volume-weighted average from that sample.</p><button class="btn btn-ghost" data-action="import" style="margin-top:20px">Import sales CSV <span>↑</span></button><p class="calc-note">CSV columns: item, unitPrice, quantity, timestamp. Item accepts a Minecraft ID or exact catalog name. Dates must include a timezone. Only Oct 1–21, 2026 sales are included. Imports stay in this browser. Item art: Minecraft textures, custom SVG icons, and AI-generated spawner artwork.</p>`,'profile-modal')}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const split=l=>(l.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)||[]).filter(x=>x!=='').map(x=>x.replace(/,$/,'').replace(/^"|"$/g,'').replace(/""/g,'"'));const heads=split(lines.shift());return lines.map(l=>Object.fromEntries(split(l).map((v,i)=>[heads[i],v])))}
async function importSales(file){try{let rows=parseCSV(await file.text()),out={},invalid=0;for(const r of rows){let raw=String(r.item||'').replace(/^minecraft:/,''),d=byId.get(raw)||DATA.find(d=>d.name.toLowerCase()===raw.toLowerCase());let price=Number(r.unitPrice),qty=Number(r.quantity),ts=String(r.timestamp||''),time=Date.parse(ts);if(!d||!Number.isFinite(price)||price<=0||!Number.isSafeInteger(qty)||qty<=0||!/(Z|[+-]\d\d:\d\d)$/.test(ts)||!Number.isFinite(time)){invalid++;continue}const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(time));if(day<'2026-10-01'||day>'2026-10-21'){invalid++;continue}let a=out[d.id]??{total:0,quantity:0,transactions:0,first:day,last:day};a.total+=price*qty;a.quantity+=qty;a.transactions++;a.first=day<a.first?day:a.first;a.last=day>a.last?day:a.last;out[d.id]=a}let count=Object.keys(out).length;if(!count){toast('No valid October sales found. Check CSV columns and dated timestamps.');return}for(const a of Object.values(out))a.average=a.total/a.quantity;history={...history,...out};save('dt-history-v2',history);closeModal();updateResults();toast(`October sample averages imported for ${count} items. ${invalid} rows skipped.`)}catch{toast('Could not read the CSV. Use item, unitPrice, quantity, timestamp columns.')}}
function updateManual(){const b=+$('#manual-buy').value,s=+$('#manual-sell').value,q=+$('#manual-qty').value;$('#manual-capital').textContent=b>0&&q>0?fmt(b*q):'—';$('#manual-profit').textContent=b>0&&s>0&&q>0?fmt((s-b)*q):'—'}
function addPlan(d,buy,sell,qty,method){plans.unshift({id:d.id,buy,sell,qty,profit:(sell-buy)*qty,method,created:new Date().toISOString()});save('dt-plans-v2',plans);toast('Trade plan saved');if($('#plans-list'))$('#plans-list').innerHTML=planList()}
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a,[data-item]');if(!el)return;
 if(el.classList.contains('skip')){ev.preventDefault();$('#content').focus();return}
 if(el.dataset.watch){ev.preventDefault();ev.stopPropagation();toggleWatch(el.dataset.watch);return}
 if(el.dataset.item){ev.preventDefault();openItem(el.dataset.item,el.dataset.context||'market');return}
 if(el.dataset.info){sourcesModal();return}
 if(el.dataset.category){state.category=el.dataset.category;state.page=1;$$('[data-category]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});updateResults();return}
 if(el.dataset.sort){state.dir=state.sort===el.dataset.sort?-state.dir:-1;state.sort=el.dataset.sort;updateResults();return}
 if(el.dataset.flipTab){location.hash='/flips?tab='+el.dataset.flipTab;return}
 if(el.dataset.page){state.page+=el.dataset.page==='next'?1:-1;updateResults();$('#results').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});return}
 if(el.dataset.removePlan!==undefined){plans.splice(+el.dataset.removePlan,1);save('dt-plans-v2',plans);$('#plans-list').innerHTML=planList();toast('Trade plan removed');return}
 switch(el.dataset.action){
  case'close':closeModal();break;
  case'profile':profileModal();break;
  case'menu':{let yes=!$('.desktop-nav').classList.contains('open');$('.desktop-nav').classList.toggle('open',yes);el.setAttribute('aria-expanded',yes);break}
  case'top':ev.preventDefault();scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'});break;
  case'reset':state.query='';state.category='All';state.budget=0;state.page=1;if($('#market-search'))$('#market-search').value='';if($('#budget'))$('#budget').value='';$$('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category==='All');b.setAttribute('aria-pressed',b.dataset.category==='All')});updateResults();break;
  case'detail-watch':if(currentItem){toggleWatch(currentItem.id);el.textContent=watch.has(currentItem.id)?'★ Watching':'☆ Add to watchlist'}break;
  case'copy-item':if(currentItem&&navigator.clipboard)navigator.clipboard.writeText(currentItem.id).then(()=>toast('Minecraft ID copied')).catch(()=>toast('Select the ID above to copy it.'));break;
  case'save-plan':if(currentItem){let b=+$('#detail-buy').value,s=+$('#detail-sell').value,q=+$('#plan-quantity').value;if(b>0&&s>0&&q>0){addPlan(currentItem,b,s,q,context==='crafting'?'Recipe quote':'Manual prices');el.textContent='Plan saved ✓';el.disabled=true}}break;
  case'import':{let input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.addEventListener('change',()=>{if(input.files[0])importSales(input.files[0])});input.click();break}
 }
});
document.addEventListener('input',ev=>{const t=ev.target;
 if(t.dataset.calc){calcUpdate(t.closest('[data-calculator]'));return}
 if(t.id==='market-search'){state.query=t.value;state.page=1;updateResults()}
 if(t.id==='budget'){state.budget=Math.max(0,+t.value||0);state.page=1;updateResults()}
 if(['detail-buy','detail-sell','plan-quantity'].includes(t.id))updateDetail();
 if(['manual-buy','manual-sell','manual-qty'].includes(t.id))updateManual();
 if(t.id==='plan-item'){let id=t.value.split(' — ').at(-1),d=byId.get(id);if(d&&d.price!=null){$('#manual-sell').value=d.price;updateManual()}}
 if(t.id==='home-search'){const q=t.value.trim().toLowerCase(),res=q?DATA.filter(d=>(d.name+' '+d.id).toLowerCase().includes(q)).slice(0,6):[];$('#home-results').innerHTML=q?`<div class="home-search-results">${res.length?res.map(d=>`<button data-item="${d.id}">${icon(d)}<span>${esc(d.name)}</span><span>${Number.isFinite(d.price)?fmt(d.price):'No quote'} ↗</span></button>`).join(''):'<p style="font-size:11px;padding:12px">No matching catalog entries.</p>'}</div>`:''}
});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='sort'){state.sort=t.value;state.dir=t.value==='name'?1:-1;state.page=1;updateResults()}if(t.id==='page-size'){state.size=+t.value;state.page=1;updateResults()}});
document.addEventListener('submit',ev=>{
 if(ev.target.id==='home-search-form'){ev.preventDefault();location.hash='/market?q='+encodeURIComponent($('#home-search').value)}
 if(ev.target.id==='profile-form'){ev.preventDefault();profile=$('#profile-name').value.trim().slice(0,24);if(profile){save('dt-profile',profile);closeModal();location.hash='/watchlist';toast('Profile saved')}}
 if(ev.target.id==='manual-plan'){ev.preventDefault();let raw=$('#plan-item').value,id=raw.split(' — ').at(-1),d=byId.get(id)||DATA.find(d=>d.name.toLowerCase()===raw.toLowerCase()),b=+$('#manual-buy').value,s=+$('#manual-sell').value,q=+$('#manual-qty').value;if(!d){toast('Choose a catalog item from the item suggestions.');return}if(b>0&&s>0&&Number.isInteger(q)&&q>0)addPlan(d,b,s,q,'Manual prices')}
});
document.addEventListener('keydown',ev=>{const dialog=$('[role="dialog"]');if(ev.key==='Escape'){closeModal();$('.desktop-nav').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');if($('#home-results'))$('#home-results').innerHTML=''}
 if(ev.key==='Tab'&&dialog){const all=$$('button,a[href],input,select,[tabindex="0"]',dialog).filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}
 if(ev.key==='Enter'&&ev.target.matches('[data-item]')&&!ev.target.matches('button')){ev.preventDefault();openItem(ev.target.dataset.item,ev.target.dataset.context||'market')}
 if(ev.key==='/'&&!dialog&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){ev.preventDefault();($('#home-search')||$('#market-search'))?.focus()}
});
document.addEventListener('click',ev=>{if(!ev.target.closest('.home-search-wrap')&&$('#home-results'))$('#home-results').innerHTML=''});
window.addEventListener('hashchange',route);window.addEventListener('scroll',onScroll,{passive:true});route();
